    16	  async batch(documentId: string, input: DiagramBatchApplication, controller: MappingDocumentController, persist: () => Promise<void>) {
    17	    const key = JSON.stringify([documentId, input.requestId]), signature = JSON.stringify(input);
    18	    let receipt = this.receipts.get(key);
    19	    if (receipt && receipt.signature !== signature) throw Error('REQUEST_ID_CONFLICT: revision application differs');
    20	    if (!receipt) {
    21	      if (this.receipts.size >= 2000) throw Error('Revision receipt capacity reached; reload the workspace');
    22	      const operations = input.edits.map(edit => edit.variants
    23	        ? { method: 'variant-store' as const, nodeId: edit.nodeId, expectedRevisionId: edit.baseRevisionId, variants: edit.variants }
    24	        : { method: 'diagram-revision-apply' as const, nodeId: edit.nodeId, expectedRevisionId: edit.baseRevisionId, revision: edit.revision });
    25	      const result = controller.applyUpdate(input.expectedVersion, [...operations, ...generatedDiagramOperations(input.creations)]);
